---@class ECSEntity
local ECSEntity = Class("ECSEntity")

local tostring = tostring

ECSEntity.events = {
    OnComponentReplaced = "OnComponentReplaced",
    OnComponentAdded = "OnComponentAdded",
    OnComponentRemoved = "OnComponentRemoved",
}
---@type ECSComponentType
local ECSComponentType = ECSComponentType or import('Game.Auto.ECSComponentType')

local function ConstructComp(compName)
    local component = require(string.format("Game.Logic.%s", compName))
    component = component.New()
    return component
end

---__init world
function ECSEntity:__init(world)
    self.id = 0
    self.name = "ECSEntity"
    self.createFrame = 0
    self.destroyFrame = 0
    self.world = world
    --甜充所有的组件列表
    self.components = {}
end


function ECSEntity:__delete()
    ---清除所有的组件
    self.id = 0
    self.name = "ECSEntity"
    self.createFrame = 0
    self.destroyFrame = 0
    self.world = nil
    if not isNull(self.components) then
        for i, v in pairs(self.components) do
            v:Delete()---component的删除动作
        end
    end
    self.components = nil
end

---World
---@param world table
function ECSEntity:World(world)
    if isTable(world) then
        self.world = world
    end
    return self.world
end

function ECSEntity:ID(id)
    if checkNumber(id) > 0 then
        self.id = id
    end
    return self.id
end

function ECSEntity:CreateFrame(frame)
    if checkNumber(frame) > 0 then
        self.createFrame = frame
    end
    return self.destroyFrame
end

function ECSEntity:DestroyFrame(frame)
    if checkNumber(frame) > 0 then
        self.destroyFrame = frame
    end
    return self.destroyFrame
end

function ECSEntity:ToHash()
    local hash = self.id
    for i, v in pairs(self.components) do
        hash = hash + v:ToHash()
    end
    return hash
end

---IsCompExists 是否存在组件
---@param index number
function ECSEntity:IsCompExists(index)
    return isSet(self.components, tostring(index))
end

---IsCompExistsByName
---@param compName string
function ECSEntity:IsCompExistsByName(compName)
    local index = ECSComponentType.GetComponentIndex(compName);
    return self:IsCompExists(index)
end

---IsCompExistsByT 指定类型的组件是否存在
---@param T table
function ECSEntity:IsCompExistsByT(T)
    return self:IsCompExistsByName(T.name)
end

---添加组件的名称对应的数据
---AddComp
---@param compName string
function ECSEntity:AddComp(compName)
    if string.isEmpty(compName) then
        return
    end
    local component = nil
    local index = ECSComponentType.GetComponentIndex(compName);
    if isSet(self.components, tostring(index)) then
        print(string.format("%s(%s|%s)", "AddComp exist comp !", compName, tostring(index)))
    else
        component = ConstructComp(compName)
        component.entity = self
        self.components[tostring(index)] = component
        --组件添加的事件回调
        if Events.HasListener(ECSEntity.events.OnComponentAdded) then
            Events.Broadcast(ECSEntity.events.OnComponentAdded, self, index, component)
        end

    end
    return component
end

---RemoveComp 移除组件
---@param compName string
function ECSEntity:RemoveComp(compName)
    if string.isEmpty(compName) then
        return
    end
    local index = ECSComponentType.GetComponentIndex(compName);
    if not isSet(self.components, tostring(index)) then
        print(string.format("%s(%s|%s)", "RemoveComp not exist comp !", compName, tostring(index)))
    else
        local component = self.components[tostring(index)]
        self.components[tostring(index)] = nil
        --组件移除的事件回调
        if Events.HasListener(ECSEntity.events.OnComponentRemoved) then
            Events.Broadcast(ECSEntity.events.OnComponentRemoved, self, index, compName)
        end
        component.entity = nil
        component.world = nil
        component:Delete()
    end
end

---GetComp 获取组件
---@param compName ECSComponent
function ECSEntity:GetComp(compName)
    if string.isEmpty(compName) then
        return
    end
    local index = ECSComponentType.GetComponentIndex(compName);
    local component = self.components[tostring(index)]
    if isTable(component) then
        return component
    else
        print(string.format("EntityID %s GetComp not exist comp ! %s ", tostring(self:ID()), tostring(compName)))
    end
end

---GetOrAddComp 添加或者获取组件
---@param compName string
function ECSEntity:GetOrAddComp(compName)
    if self:IsCompExistsByName(compName) then
        return self:GetComp(compName)
    end
    return self:AddComp(compName)
end


---ChangeComp 切换组件位置
---@param compName string
---@param compNewName string
function ECSEntity:ChangeComp(compName, compNewName)
    local index = ECSComponentType.GetComponentIndex(compName);
    local oldComp = self.components[tostring(index)]
    if not isTable(oldComp) then
        print(string.format("EntityID %s GetComp not exist comp ! %s ", tostring(self:ID()), tostring(compNewName)))
    else
        oldComp.entity = nil
        local component = ConstructComp(compNewName)
        self.components[tostring(index)] = component
        component.entity = self
        component.world = self:World()
        Events.Broadcast(ECSEntity.events.OnComponentReplaced, self, index, oldComp, component)
    end
end

return ECSEntity